def main():
    os.environ.setdefault('PYGAME_HIDE_SUPPORT_PROMPT', '1')
    try:
        import pygame
    except ModuleNotFoundError as error:
        if error.name != 'pygame':
            raise
        run_tkinter()
    else:
        run_pygame(pygame)


if __name__ == '__main__':
    main()
